U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in U:
 x=get_stock_daily_data(s,days=4000)
 if x is not None and len(x): D[s]=x.assign(date=pd.to_datetime(x.date)).drop_duplicates('date').set_index('date').close
p=pd.DataFrame(D).sort_index().ffill()
v=pd.read_csv('../persistent/index_data/VIX.csv'); v['date']=pd.to_datetime(v['date']); vc=[c for c in v.columns if c.lower() in ('close','adj_close','value')][0]; vs=v.set_index('date')[vc].reindex(p.index).ffill()
# Continuous stress-aware short reversal: oversold signal amplified when VIX is rising and elevated versus its 20d baseline.
vr=vs.pct_change(5); stress=(vr/vr.rolling(60).std()).clip(-3,3).fillna(0)
r5=p.pct_change(5); sig=-r5*(1+0.5*stress.clip(lower=0))
rows=[]
