from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
end=pd.Timestamp('2030-06-27')
D={s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date')['close'].rename(s) for s in U}
p=pd.concat(D,axis=1).sort_index().loc[:end]; r=p.pct_change()
# Trend quality: medium-term relative return, penalized by downside volatility and path noise.
med=r.median(axis=1)
rel=r.sub(med,axis=0).rolling(40,min_periods=30).sum()
down=r.where(r<0,0).rolling(40,min_periods=30).std()
path=r.rolling(40,min_periods=30).std()
quality=rel.div(path+1e-8).mul(1/(1+down/(path+1e-8)))
f=quality.shift(1)
out=[]
for h in [10,20,40,60]:
 y=p.shift(-h)/p-1; a=[]
 for dt in p.index:
  z=pd.concat([f.loc[dt],y.loc[dt]],axis=1).dropna()
  if len(z)>=8:
   q=spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic
   if np.isfinite(q): a.append((dt,q,len(z)))
 a=pd.DataFrame(a,columns=['date','ic','n']); ic=a.ic.mean(); ir=ic/(a.ic.std(ddof=1)+1e-12)
 print('horizon',h,'dates',len(a),'avg_n',round(a.n.mean(),2),'coverage',round(a.n.mean()/15,4),'IC',round(ic,6),'ICIR',round(ir,6),'hit',round((a.ic>0).mean(),4))
 if h==40:
  for name,sl in [('2024-2026',a[(a.date>='2024-01-01')&(a.date<='2026-12-31')]),('2027-2030',a[a.date>='2027-01-01'])]: print('regime',name,'dates',len(sl),'IC',round(sl.ic.mean(),6),'ICIR',round(sl.ic.mean()/(sl.ic.std(ddof=1)+1e-12),6))
rank=f.rank(axis=1,pct=True); print('turnover_proxy',round(rank.diff().abs().mean(axis=1).dropna().mean(),6)); f.index.name='date'; f.to_csv('scripts/miner_1_20300627_downside_stability_trend_signal.csv')

